'''Completer for a key-value pair, generated by a command.'''

from ..bash_complete import BashCompletionFunc
from ..fish_complete import FishCompletionCommand
from ..zsh_complete import ZshComplFunc
from ..scheme_validator import (
    check_type, check_char, check_non_empty_string)
from ..helpers import ShellFunction
from ..helpers import FishFunction
from ..bash_helpers import BashHelpers
from ..fish_helpers import FishHelpers
from ..zsh_helpers import ZshHelpers

CATEGORY = 'custom'

SYNOPSIS = r'''
['key_value_pair_exec', <VALUE_SEPARATOR>, <COMMAND>]
'''

SHORT = 'Complete dynamically generated a key=value pairs'

LONG = r'''
`VALUE_SEPARATOR`:
  The separator used to separate a key from its value.

`COMMAND`:
  The command or function used to generate the available keys and values.

  If invoked without arguments, it must output the available keys in the
  following format:

  ```
  <KEY_1>[=]\t<DESCRIPTION_1>
  <KEY_2>[=]\t<DESCRIPTION_2>
  [...]
  ```

  Appending `=` to a key indicates that it requires a value.

  If invoked with a single argument, the argument is the selected key. The
  command must output the possible values for that key in the following
  format:

  ```
  <ITEM_1>\t<DESCRIPTION_1>
  <ITEM_2>\t<DESCRIPTION_2>
  [...]
  ```

  Each line represents one completion candidate. The item and its description
  are separated by a tab character.

Example function:

```sh
_complete_key_value_pair() {
  if (( $# == 0 )); then
    printf '%s\t%s\n'    \
      'flag'    'a flag' \
      'option=' 'option with value'
  else
    case '$1' in
      option)
        printf '%s\t%s\n'     \
          'foo' 'a foo value' \
          'bar' 'a bar value';;
      esac
  fi
}
```
'''

ALSO = {
    'key_value_pair': 'For completing single key=value pairs',
}

NOTES = [
    'Functions can be put inside a file and included with `--include-file`',
]

DEFINITION = r'''
prog: 'example'
options:
  - option_strings: ['-o']
    complete: ['key_value_pair_exec', '=', '_complete_key_value_pair']
'''

OUTPUT = r'''
~ > example -o <TAB>
flag    -- a flag
option  -- option with value

~ > example -o option=<TAB>
foo     -- a foo value
bar     -- a bar value
'''

_KEY_VALUE_PAIR_EXEC_BASH = ShellFunction('key_value_pair_exec', r'''
local sep="$1"
local func="$2"

local strip_chars=''
[[ "$COMP_WORDBREAKS" == *"$sep"* ]] && strip_chars+="$sep"
[[ "${cur:0:1}" == '"' ]] && strip_chars=''
[[ "${cur:0:1}" == "'" ]] && strip_chars=''
local cur="$cur" break_pos in_quotes
dequote "$cur" cur break_pos in_quotes

local key="${cur%%"$sep"*}" value="${cur#*"$sep"}" cur_stripped="$cur"

COMPREPLY=()

if [[ "$cur" != *"$sep"* ]]; then
  exec "$func"
else
  cur="$value"
  exec "$func $key"

  cur_stripped="${cur_stripped:0:$(( ${#cur_stripped} - ${#value} ))}"
  if [[ -n "$strip_chars" ]]; then
      cur_stripped="${cur_stripped##*[$strip_chars]}"
  fi

  for i in "${!COMPREPLY[@]}"; do
    COMPREPLY[i]="$cur_stripped${COMPREPLY[i]}"
  done
fi
''', ['dequote', 'exec'])

_KEY_VALUE_PAIR_EXEC_FISH = FishFunction('key_value_pair_exec', r'''
set -l sep $argv[1]
set -l func $argv[2]
set -l comp (get_completing_arg)
set -l split (string split -m1 -- $sep $comp)

if test (count $split) -eq 2
  set -l value
  set -g __fish_stripprefix "^.*"(string escape --style=regex -- $sep)
  for value in ($func $split[1])
    printf '%s%s%s\n' $split[1] $sep $value
  end
  set -e __fish_stripprefix
else
  $func
end
''', ['get_completing_arg'])

_KEY_VALUE_PAIR_EXEC_ZSH = ShellFunction('key_value_pair_exec', r'''
local sep="$1"
local func="$2"
local key='' desc=''
local -a args=()

while IFS=$'\t' read -r key desc; do
  desc="${desc//\\/\\\\}"
  desc="${desc//:/\\:}"
  desc="${desc//\[/\\[}"
  desc="${desc//\]/\\]}"

  if [[ "${key[-1]}" == '=' ]]; then
    key="${key:0:-1}"
    args+=("${key}[$desc]:::{exec '$func $key'}")
  else
    args+=("${key}[$desc]")
  fi
done < <(eval "$func")

_values -S "$sep" '' "${args[@]}"
''', ['exec'])

BashHelpers.add_function(_KEY_VALUE_PAIR_EXEC_BASH)
FishHelpers.add_function(_KEY_VALUE_PAIR_EXEC_FISH)
ZshHelpers.add_function(_KEY_VALUE_PAIR_EXEC_ZSH)


def validate(_ctxt, arguments):
    '''Validate YAML for key_value_pair_exec completer'''
    value_separator = arguments.get_required_arg('value_separator')
    command = arguments.get_required_arg('command')
    arguments.require_no_more()

    check_type(value_separator, (str,), 'value_separator')
    check_char(value_separator, 'value_separator')
    check_type(command, (str,), 'command')
    check_non_empty_string(command, 'command')


def bash(_completer, ctxt, _trace, value_separator, command):
    '''Implement key_value_pair_exec for bash'''
    func = ctxt.helpers.use_function('key_value_pair_exec')
    return BashCompletionFunc(ctxt, [func, value_separator, command])


def fish(_completer, ctxt, _trace, value_separator, command):
    '''Implement key_value_pair_exec for fish'''
    func = ctxt.helpers.use_function('key_value_pair_exec')
    return FishCompletionCommand(ctxt, [func, value_separator, command])


def zsh(_completer, ctxt, _trace, value_separator, command):
    '''Implement key_value_pair_exec for zsh'''
    func = ctxt.helpers.use_function('key_value_pair_exec')
    return ZshComplFunc(
        ctxt, [func, value_separator, command], needs_braces=True)
